const items = $input.all();

function text(value) {
  return String(value ?? '').trim();
}

function clean(value) {
  return text(value).replace(/\s+/g, ' ');
}

function formatTimeline(timeline) {
  return (Array.isArray(timeline) ? timeline : [])
    .slice(-20)
    .map((entry) => {
      const direction = clean(entry.direction).toLowerCase() || 'message';
      const author = clean(entry.sender_name ?? entry.author ?? (direction === 'outbound' ? 'Atendente' : 'Cliente')) || (direction === 'outbound' ? 'Atendente' : 'Cliente');
      const body = clean(entry.body);
      return '- ' + author + ' (' + direction + '): ' + body;
    })
    .join('\n');
}

function formatKnowledge(matches) {
  return (Array.isArray(matches) ? matches : [])
    .slice(0, 5)
    .map((match, index) => {
      const title = clean(match.title || ('Trecho ' + (index + 1)));
      const content = clean(match.content || '');
      return String(index + 1) + '. ' + title + '\n' + content;
    })
    .join('\n\n---\n\n');
}

return items.map((item) => {
  const payload = item.json ?? {};
  const company = payload.company ?? payload.content?.company ?? {};
  const conversation = payload.conversation ?? payload.content?.conversation ?? {};
  const agent = payload.agent ?? payload.content?.agent ?? {};
  const timeline = Array.isArray(payload.timeline) ? payload.timeline : [];
  const knowledgeMatches = Array.isArray(payload.knowledge_matches) ? payload.knowledge_matches : [];
  const knowledgeBase = clean(payload.knowledge_base ?? payload.content?.knowledge_base ?? '');
  const companyId = payload.company_id ?? payload.content?.company_id ?? company.id ?? 'unknown';
  const conversationId = payload.conversation_id ?? payload.content?.conversation_id ?? conversation.id ?? 'unknown';
  const assistantName = clean(agent.name ?? 'Copiloto') || 'Copiloto';
  const companyName = clean(company.trade_name ?? company.name ?? payload.company_name ?? 'a empresa') || 'a empresa';
  const draftBody = text(payload.message?.body ?? payload.content?.message?.body ?? payload.chatInput ?? payload.content?.chatInput ?? payload.request?.message ?? '');
  const latestRelevantMessage = [...timeline].reverse().find((entry) => {
    const direction = clean(entry?.direction).toLowerCase();
    return (direction === 'inbound' || direction === 'customer') && text(entry?.body);
  });
  const targetMessage = draftBody || text(latestRelevantMessage?.body ?? (timeline.length > 0 ? timeline[timeline.length - 1]?.body : '') ?? '');
  const sessionKey = 'copilot:' + companyId + ':' + conversationId;

  const systemMessage = [
    'Você é o Copiloto de atendimento da ' + companyName + '.',
    'Sua função é apoiar o atendente humano sugerindo uma resposta pronta e natural para copiar no composer.',
    'Responda sempre em português do Brasil.',
    'Tom: humano, consultivo, direto e cordial.',
    'A base de conhecimento do Supabase é a fonte principal.',
    'Antes de redigir qualquer resposta técnica, consulte a ferramenta "Base de conhecimento" com a pergunta principal do cliente e use apenas os trechos realmente relevantes.',
    'Se a base retornar apenas conteúdo genérico ou de apresentação da empresa, ignore isso para esta resposta e procure um trecho mais específico.',
    'Se a informação ainda não estiver completa depois da consulta, sugira uma pergunta de esclarecimento curta ou sinalize handoff para um humano.',
    'Use o histórico da conversa como contexto de apoio, mas nunca substitua a base vetorial por texto genérico.',
    'Não fale com o cliente em primeira pessoa como se você fosse o bot final.',
    'Não explique o raciocínio.',
    'Não use markdown.',
    'Retorne somente JSON válido com as chaves: suggestion, confidence, summary, notes, assistant_name.'
  ].join('\n');

  const chatInput = [
    'Empresa: ' + companyName,
    'Atendente que pediu ajuda: ' + text(payload.requested_by_user_name ?? payload.content?.requested_by_user_name ?? 'Atendente'),
    'Agente: ' + assistantName,
    'Session key: ' + sessionKey,
    'Pergunta principal para consulta na base: ' + targetMessage,
    '',
    'Mensagem alvo da sugestão:',
    targetMessage || '(sem mensagem alvo)',
    '',
    'Histórico recente da conversa:',
    formatTimeline(timeline) || 'Sem histórico adicional.',
    '',
    'Base técnica relevante (apenas apoio):',
    formatKnowledge(knowledgeMatches) || 'Nenhum trecho destacado.',
    '',
    'Base técnica complementar legada (fallback; não trate como fonte principal se a ferramenta Supabase retornar algo útil):',
    knowledgeBase || 'Base técnica vazia.',
    '',
    'Objetivo:',
    'Gere uma sugestão de resposta que o atendente possa enviar quase sem editar.'
  ].join('\n');

  return {
    json: {
      ...payload,
      company,
      conversation,
      agent,
      company_id: companyId,
      conversation_id: conversationId,
      assistant_name: assistantName,
      session_key: sessionKey,
      systemMessage,
      chatInput,
      message: payload.message ?? payload.content?.message ?? {},
      replied_to_message_id: Number(payload.message_id ?? payload.replied_to_message_id ?? 0) || null,
      external_message_id: String(payload.external_message_id ?? ('copilot-response:' + (payload.message_id ?? Date.now()))),
    },
  };
});

const items = $input.all();

function text(value) {
  return String(value ?? '').trim();
}

function stripCodeFences(raw) {
  return String(raw ?? '')
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .replace(/^\s*json\s*/i, '')
    .trim();
}

function extractJsonCandidate(raw) {
  const cleaned = stripCodeFences(raw);
  if (!cleaned) {
    return '';
  }

  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return cleaned.slice(firstBrace, lastBrace + 1).trim();
  }

  return cleaned;
}

function parseMaybeJson(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return value;
  }

  const raw = text(value);
  if (!raw) {
    return {};
  }

  const candidates = [raw, stripCodeFences(raw), extractJsonCandidate(raw)];
  for (const candidate of candidates) {
    if (!candidate) continue;
    try {
      const parsed = JSON.parse(candidate);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        return parsed;
      }
    } catch (error) {
      // Try next candidate.
    }
  }

  return { suggestion: stripCodeFences(raw) };
}

function safeContext() {
  try {
    const items = $items('Preparar Contexto');
    if (Array.isArray(items) && items.length > 0 && items[0]?.json) {
      return items[0].json;
    }
  } catch (error) {
    // Fallback to the current payload when the paired item lookup is unavailable.
  }

  return {};
}

return items.map((item) => {
  const payload = item.json ?? {};
  const context = safeContext();
  const aiOutput = parseMaybeJson(
    payload.output ?? payload.response ?? payload.text ?? payload.message ?? payload.content ?? payload.answer ?? ''
  );

  const suggestion = text(
    aiOutput.suggestion
    ?? aiOutput.reply
    ?? payload.suggestion
    ?? payload.reply
    ?? payload.output
    ?? payload.response
    ?? payload.text
    ?? payload.message
    ?? payload.content
    ?? payload.answer
  );

  const companyId = Number(context.company_id ?? payload.company_id ?? payload.content?.company_id ?? 0) || null;
  const conversationId = Number(context.conversation_id ?? payload.conversation_id ?? payload.content?.conversation_id ?? 0) || null;
  const requestId = text(context.request_id ?? payload.request_id ?? payload.copilot_request_id ?? '');
  const requestedByUserId = Number(context.requested_by_user_id ?? payload.requested_by_user_id ?? payload.content?.requested_by_user_id ?? 0) || null;
  const requestedByUserName = text(context.requested_by_user_name ?? payload.requested_by_user_name ?? payload.content?.requested_by_user_name ?? 'Atendente') || 'Atendente';
  const assistantName = text(aiOutput.assistant_name ?? payload.assistant_name ?? context.assistant_name ?? 'Copiloto') || 'Copiloto';

  return {
    json: {
      ...context,
      ...payload,
      ...aiOutput,
      company_id: companyId,
      conversation_id: conversationId,
      request_id: requestId,
      copilot_request_id: requestId,
      requested_by_user_id: requestedByUserId,
      requested_by_user_name: requestedByUserName,
      assistant_name: assistantName,
      session_key: text(context.session_key ?? payload.session_key ?? ''),
      suggestion,
      reply: suggestion,
      handoff_to_human: Boolean(aiOutput.handoff_to_human ?? payload.handoff_to_human ?? false),
      confidence: Number(aiOutput.confidence ?? payload.confidence ?? 0.9),
      category: text(aiOutput.category ?? payload.category ?? 'copiloto') || 'copiloto',
      notes: text(aiOutput.notes ?? payload.notes ?? ''),
      summary: text(aiOutput.summary ?? payload.summary ?? ''),
      handoff_message: text(aiOutput.handoff_message ?? payload.handoff_message ?? ''),
    },
  };
});
